SELECT TO_DATE(txn_time) AS txn_day, CASE WHEN amount >= 3500 THEN 'high' WHEN amount >= 1600 THEN 'mid' ELSE 'low' END AS amount_bucket, COUNT(*) AS transaction_count FROM transactions WHERE merchant = 'Shell' AND HOUR(txn_time) BETWEEN 12 AND 20 GROUP BY TO_DATE(txn_time), CASE WHEN amount >= 3500 THEN 'high' WHEN amount >= 1600 THEN 'mid' ELSE 'low' END HAVING COUNT(*) < 2 ORDER BY txn_day;
